s", "child_schema": "private", "tgdeferrable": false, "constraint_def": "FOREIGN KEY (source_id) REFERENCES private.sources(id)", "tginitdeferred": false, "function_schema": "pg_catalog"}, {"tgtype": 9, "nspname": "private", "proname": "RI_FKey_noaction_del", "relname": "stories", "tgenabled": "O", "child_table": "issues", "child_schema": "private", "tgdeferrable": false, "constraint_def": "FOREIGN KEY (story_id) REFERENCES private.stories(id)", "tginitdeferred": false, "function_schema": "pg_catalog"}, {"tgtype": 9, "nspname": "private", "proname": "RI_FKey_noaction_del", "relname": "stories", "tgenabled": "O", "child_table": "ranking_entries", "child_schema": "private", "tgdeferrable": false, "constraint_def": "FOREIGN KEY (story_id) REFERENCES private.stories(id)", "tginitdeferred": false, "function_schema": "pg_catalog"}, {"tgtype": 9, "nspname": "private", "proname": "RI_FKey_noaction_del", "relname": "subgroups", "tgenabled": "O", "child_table": "catalog_memberships", "child_schema": "private", "tgdeferrable": false, "constraint_def": "FOREIGN KEY (subgroup_id) REFERENCES private.subgroups(id)", "tginitdeferred": false, "function_schema": "pg_catalog"}, {"tgtype": 9, "nspname": "private", "proname": "RI_FKey_noaction_del", "relname": "subgroups", "tgenabled": "O", "child_table": "catalog_memberships", "child_schema": "private", "tgdeferrable": true, "constraint_def": "FOREIGN KEY (subgroup_id, sector_id) REFERENCES private.subgroups(id, sector_id) DEFERRABLE", "tginitdeferred": false, "function_schema": "pg_catalog"}, {"tgtype": 9, "nspname": "private", "proname": "RI_FKey_noaction_del", "relname": "subgroups", "tgenabled": "O", "child_table": "sector_companies", "child_schema": "private", "tgdeferrable": false, "constraint_def": "FOREIGN KEY (subgroup_id) REFERENCES private.subgroups(id)", "tginitdeferred": false, "function_schema": "pg_catalog"}]'::jsonb then raise exception 'BASELINE_INTERNAL_RI';end if;

execute $c08a_source$create function private.search_normalize(p_text text) returns text language sql immutable set search_path='' as $$
 select lower(normalize(regexp_replace(btrim(coalesce(p_text,'')),'[[:space:]]+',' ','g'),NFC))
$$;
create function private.search_tokens(p_query text) returns text[] language plpgsql immutable set search_path='' as $$
declare words text[];q text;
begin
 if p_query is null or length(p_query) not between 1 and 80 then raise exception 'INVALID_SEARCH_QUERY';end if;
 q:=private.search_normalize(p_query);words:=string_to_array(q,' ');
 if q='' or cardinality(words)>6 or q~'[[:cntrl:]]' then raise exception 'INVALID_SEARCH_QUERY';end if;
 return words;
end$$;
create function private.search_contains_all(p_text text,p_tokens text[]) returns boolean language sql immutable set search_path='' as $$
 select not exists(select 1 from unnest(p_tokens) word where strpos(private.search_normalize(p_text),word)=0)
$$;
create function private.search_membership_visible(p_membership uuid,p_head bigint) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from private.catalog_memberships m join private.catalog_source_companies c on c.id=m.source_company_ref and c.active
 where m.id=p_membership and m.active and private.catalog_sector_selectable(m.sector_id,p_head,'SYNTHETIC')
 and (m.subgroup_id is null or exists(select 1 from private.subgroups g where g.id=m.subgroup_id and g.sector_id=m.sector_id and g.active and g.metadata_kind='USER_REFERENCE_UNVERIFIED')))
$$;
create function private.search_company_sectors(p_company uuid,p_head bigint,p_offset integer,p_limit integer) returns jsonb language sql stable set search_path='' as $$
 select coalesce(jsonb_agg(to_jsonb(page) order by page.display_order,page.id),'[]') from(
 select distinct s.id,s.name,s.display_order from private.catalog_memberships m join private.sectors s on s.id=m.sector_id
 where m.source_company_ref=p_company and private.search_membership_visible(m.id,p_head)
 order by s.display_order,s.id offset p_offset limit p_limit)page
$$;
create function public.catalog_public_search_news(p_expected bigint,p_query text,p_limit integer default 20,p_as_of timestamptz default null,p_last_time timestamptz default null,p_last_id uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;words text[];cutoff timestamptz;items jsonb;last_item jsonb;
begin
 head:=private.catalog_require_reference_head(p_expected);words:=private.search_tokens(p_query);cutoff:=coalesce(p_as_of,statement_timestamp());
 if p_limit is null or p_limit not between 1 and 20 or cutoff>statement_timestamp()+interval '5 seconds' or cutoff<'2000-01-01T00:00:00Z'::timestamptz
 or (p_last_time is null)<>(p_last_id is null) or p_last_time>cutoff then raise exception 'INVALID_CURSOR_CONTEXT';end if;
 select coalesce(jsonb_agg(to_jsonb(page) order by page.first_published_at desc,page.issue_id),'[]') into items from(
  select n.issue_id,n.version_id,n.title,n.summary,n.first_published_at,n.material_change_at,n.sample_kind,v.public_body->>'article_kind' article_kind,s.id sector_id,s.name sector_name,
   coalesce(s.metadata_kind='SYNTHETIC_FIXTURE',false) legacy_sector
  from public.news_public n join private.issues i on i.id=n.issue_id and i.current_version_id=n.version_id
  join private.article_versions v on v.id=n.version_id left join private.sectors s on s.id=i.primary_sector_id and s.active
  where n.publication_state='PUBLISHED' and n.sample_kind='SYNTHETIC' and i.sample_kind='SYNTHETIC' and v.public_body->>'_contract'='M1'
   and not exists(select 1 from private.issue_aliases a where a.alias_id=n.issue_id) and private.m1_current_evidence(n.issue_id)
   and n.first_published_at<=cutoff and v.created_at<=cutoff
   and (p_last_time is null or n.first_published_at<p_last_time or n.first_published_at=p_last_time and n.issue_id>p_last_id)
   and private.search_contains_all(concat_ws(' ',n.title,n.summary,v.public_body->>'issue_analysis',
    (select string_agg(value,' ') from jsonb_array_elements_text(v.public_body->'key_issues')),
    (select string_agg(coalesce(kw->>'raw',kw->>'value'),' ') from private.catalog_sector_data d cross join lateral jsonb_array_elements(d.keywords)kw
     where private.catalog_sector_selectable(d.sector_id,head,'SYNTHETIC') and (d.sector_id=i.primary_sector_id or exists(select 1 from private.impacts z where z.version_id=v.id and z.sector_id=d.sector_id)))),words)
  order by n.first_published_at desc,n.issue_id limit p_limit+1)page;
 if jsonb_array_length(items)>p_limit then items:=items-p_limit;last_item:=items->(p_limit-1);end if;
 return jsonb_build_object('catalog_version',head::text,'as_of',cutoff,'items',items,'next',case when last_item is null then null else jsonb_build_object('last_time',last_item->'first_published_at','last_id',last_item->'issue_id') end);
end$$;
create function public.catalog_public_search_companies(p_expected bigint,p_query text,p_limit integer default 20,p_last_rank integer default null,p_last_name text default null,p_last_id uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;words text[];q text;items jsonb:='[]';item jsonb;last_item jsonb;more boolean:=false;used_bytes integer:=0;
begin
 head:=private.catalog_require_reference_head(p_expected);words:=private.search_tokens(p_query);q:=private.search_normalize(p_query);
 if p_limit is null or p_limit not between 1 and 20 or not (num_nonnulls(p_last_rank,p_last_name,p_last_id)=0 or
 (num_nonnulls(p_last_rank,p_last_name,p_last_id)=3 and p_last_rank between 0 and 3 and length(p_last_name) between 1 and 200)) then raise exception 'INVALID_CURSOR_CONTEXT';end if;
 for item in
  with matched as(
   select c.*,private.search_normalize(c.name) collate "C" sort_name,
    case when private.search_normalize(c.name)=q then 0
     when exists(select 1 from jsonb_array_elements(c.direct_keywords)kw where private.search_normalize(coalesce(kw->>'raw',kw->>'value'))=q) then 1
     when private.search_contains_all(c.name,words) then 2 else 3 end sort_rank
   from private.catalog_source_companies c where c.active and c.metadata_kind='USER_REFERENCE_UNVERIFIED'
    and exists(select 1 from private.catalog_memberships m where m.source_company_ref=c.id and private.search_membership_visible(m.id,head))
    and private.search_contains_all(concat_ws(' ',c.name,(select string_agg(coalesce(kw->>'raw',kw->>'value'),' ') from jsonb_array_elements(c.direct_keywords)kw)),words)
  ),page as(
   select m.* from matched m where p_last_rank is null or (m.sort_rank,m.sort_name collate "C",m.id)>(p_last_rank,p_last_name collate "C",p_last_id)
   order by m.sort_rank,m.sort_name collate "C",m.id limit p_limit+1
  ) select jsonb_build_object('source_company_ref',id,'name',name,'search_description',search_description,'metadata_kind',metadata_kind,'stock_identity_state',stock_identity_state,
    'stock_code',null,'price',null,'change_percent',null,'stock_url',null,'related_sectors',private.search_company_sectors(id,head,0,3),
    'has_more_sectors',jsonb_array_length(private.search_company_sectors(id,head,3,1))>0,'sort_rank',sort_rank,'sort_name',sort_name)
   from page order by sort_rank,sort_name collate "C",id
 loop
  -- Keep the complete E description, including multiline source values. A byte
  -- budget can shorten a page; it never truncates the stored/displayed text.
  if jsonb_array_length(items)>=p_limit or used_bytes+octet_length(item::text)>220000 then more:=true;exit;end if;
  used_bytes:=used_bytes+octet_length(item::text);items:=items||jsonb_build_array(item);last_item:=item;
 end loop;
 if more and last_item is null then raise exception 'PUBLIC_RESPONSE_LIMIT';end if;
 return jsonb_build_object('catalog_version',head::text,'items',(select coalesce(jsonb_agg(value-'sort_rank'-'sort_name' order by n),'[]') from jsonb_array_elements(items)with ordinality x(value,n)),
  'next',case when not more then null else jsonb_build_object('last_rank',last_item->'sort_rank','last_name',last_item->'sort_name','last_id',last_item->'source_company_ref') end);
end$$;
create function public.catalog_public_company_sectors(p_expected bigint,p_company uuid,p_offset integer default 0,p_limit integer default 20) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;items jsonb;more boolean;
begin
 head:=private.catalog_require_reference_head(p_expected);
 if p_offset is null or p_offset not between 0 and 3000 or p_limit is null or p_limit not between 1 and 20 then raise exception 'INVALID_CURSOR_CONTEXT';end if;
 if not exists(select 1 from private.catalog_source_companies c where c.id=p_company and c.active and exists(select 1 from private.catalog_memberships m where m.source_company_ref=c.id and private.search_membership_visible(m.id,head))) then
  return jsonb_build_object('catalog_version',head::text,'state','NOT_FOUND','items','[]'::jsonb,'next_offset',null);end if;
 items:=private.search_company_sectors(p_company,head,p_offset,p_limit+1);more:=jsonb_array_length(items)>p_limit;if more then items:=items-p_limit;end if;
 return jsonb_build_object('catalog_version',head::text,'state','AVAILABLE','items',items,'next_offset',case when more then p_offset+p_limit else null end);
end$$;
create function public.catalog_public_saved(p_expected bigint,p_issues uuid[]) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare head bigint;requested uuid;r jsonb;card jsonb;canonical uuid;items jsonb:='[]';
begin
 head:=private.catalog_require_reference_head(p_expected);
 if p_issues is null or cardinality(p_issues)>20 or array_position(p_issues,null) is not null or cardinality(p_issues)<>(select count(distinct id)from unnest(p_issues)id) then raise exception 'INVALID_SAVED_IDS';end if;
 foreach requested in array p_issues loop
  begin
   r:=public.resolve_issue(requested);canonical:=(r->>'canonical_issue_id')::uuid;card:=null;
   if r->>'state'='PUBLISHED' then
    if not exists(select 1 from private.issues i join private.article_versions v on v.id=i.current_version_id where i.id=canonical and i.sample_kind='SYNTHETIC' and v.public_body->>'_contract'='M1') then
     r:=jsonb_build_object('state','NOT_FOUND','message','현재 제공하지 않는 글');
    elsif not private.m1_current_evidence(canonical) then
     r:=jsonb_build_object('state','CORRECTION_PENDING','message','내용 확인 중 · 기존 내용 제공 중지','canonical_issue_id',canonical);
    else
     select jsonb_build_object('issue_id',n.issue_id,'version_id',n.version_id,'title',n.title,'summary',n.summary,'first_published_at',n.first_published_at,'material_change_at',n.material_change_at,'sample_kind',n.sample_kind,
      'article_kind',v.public_body->>'article_kind','sector_id',s.id,'sector_name',s.name,'legacy_sector',coalesce(s.metadata_kind='SYNTHETIC_FIXTURE',false)) into card
     from public.news_public n join private.issues i on i.id=n.issue_id and i.current_version_id=n.version_id join private.article_versions v on v.id=n.version_id
     left join private.sectors s on s.id=i.primary_sector_id and s.active where n.issue_id=canonical and n.publication_state='PUBLISHED' and n.sample_kind='SYNTHETIC';
     if card is null then r:=jsonb_build_object('state','NOT_FOUND','message','현재 제공하지 않는 글');else r:=jsonb_build_object('state','PUBLISHED','canonical_issue_id',canonical,'card',card);end if;
    end if;
   end if;
  exception when raise_exception then
   if sqlerrm not in ('ALIAS_CYCLE','ALIAS_CHAIN_LIMIT') then raise;end if;
   r:=jsonb_build_object('state','NOT_FOUND','message','현재 제공하지 않는 글');
  end;
  items:=items||jsonb_build_array(r||jsonb_build_object('requested_issue_id',requested));
 end loop;
 return jsonb_build_object('catalog_version',head::text,'items',items);
end$$;
alter table private.installation_settings add column settings_revision bigint not null default 1 check(settings_revision>0);
create table private.installation_setting_changes (
 id uuid primary key default gen_random_uuid(),
 installation_id uuid not null references private.installations(id),
 settings_revision bigint not null,
 reason text not null check(reason in ('SETTINGS_CHANGED','INACTIVE_SECTOR_REMOVED')),
 removed_sectors jsonb not null default '[]',
 occurred_at timestamptz not null default clock_timestamp()
);
alter table private.installation_setting_changes enable row level security;
create index installation_changes_owner_time on private.installation_setting_changes(installation_id,occurred_at desc);
create function private.installation_settings_revision() returns trigger language plpgsql set search_path='' as $$
declare removed jsonb;
begin
 if row(new.morning_issue,new.closing_issue,new.favorite_sector_issue,new.sector_ids)
  is not distinct from row(old.morning_issue,old.closing_issue,old.favorite_sector_issue,old.sector_ids) then
  new.settings_revision:=old.settings_revision;return new;
 end if;
 new.settings_revision:=old.settings_revision+1;new.updated_at:=clock_timestamp();
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name) order by u.n),'[]') into removed
 from unnest(old.sector_ids) with ordinality u(id,n) join private.sectors s on s.id=u.id
 where not u.id=any(new.sector_ids) and not s.active;
 insert into private.installation_setting_changes(installation_id,settings_revision,reason,removed_sectors)
 values(new.installation_id,new.settings_revision,case when jsonb_array_length(removed)>0 then 'INACTIVE_SECTOR_REMOVED' else 'SETTINGS_CHANGED' end,removed);
 return new;
end$$;
create trigger installation_settings_revision before update on private.installation_settings
 for each row execute function private.installation_settings_revision();
create function private.installation_settings_json(p_install uuid) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('morning_issue',s.morning_issue,'closing_issue',s.closing_issue,
 'favorite_sector_issue',s.favorite_sector_issue,'sector_ids',s.sector_ids,'settings_revision',s.settings_revision,
 'catalog_version',(select version from private.catalog_head where singleton))
 from private.installation_settings s where installation_id=p_install
$$;
create function public.installation_settings_save(p_install uuid,p_secret text,p_version integer,p_catalog bigint,p_revision bigint,
 p_morning boolean,p_closing boolean,p_favorite boolean,p_sectors uuid[]) returns jsonb
 language plpgsql security definer set search_path='' as $$
declare h bigint;v_settings private.installation_settings;
begin
 perform private.assert_server();perform private.assert_initialized();
 select version into h from private.catalog_head where singleton for share;
 perform private.assert_installation(p_install,p_secret,p_version);
 select * into strict v_settings from private.installation_settings where installation_id=p_install for update;
 if p_catalog is distinct from h or p_revision is distinct from v_settings.settings_revision then raise exception 'SETTINGS_CONFLICT';end if;
 if p_morning is null or p_closing is null or p_favorite is null or p_sectors is null or cardinality(p_sectors)>56
 or cardinality(p_sectors)<>(select count(distinct x) from unnest(p_sectors) x) then raise exception 'INVALID_SETTINGS';end if;
 if exists(select 1 from unnest(p_sectors) x where not exists(select 1 from private.sectors s
  join private.sectors parent on parent.id=s.parent_id and parent.active
  where s.id=x and s.active and s.catalog_kind='LEAF' and s.metadata_kind='USER_REFERENCE_UNVERIFIED')) then raise exception 'INACTIVE_SECTOR';end if;
 update private.installation_settings set morning_issue=p_morning,closing_issue=p_closing,
 favorite_sector_issue=p_favorite,sector_ids=p_sectors where installation_id=p_install;
 return private.installation_settings_json(p_install);
end$$;
create function public.installation_settings_read(p_install uuid,p_secret text,p_version integer) returns jsonb
 language plpgsql security definer set search_path='' as $$
begin
 perform private.assert_server();perform private.assert_initialized();perform private.assert_installation(p_install,p_secret,p_version);
 return jsonb_build_object('settings',private.installation_settings_json(p_install),'history',coalesce((select jsonb_agg(x order by x.occurred_at desc) from
  (select settings_revision,reason,removed_sectors,occurred_at from private.installation_setting_changes
   where installation_id=p_install and occurred_at>clock_timestamp()-interval '30 days' order by occurred_at desc limit 100) x),'[]'),
 'notifications',coalesce((select jsonb_agg(x order by x.cutoff desc) from
  (select d.id,d.issue_id,d.notification_type,d.cutoff from private.notification_deliveries d
   where d.installation_id=p_install and d.status='DELIVERED' order by d.cutoff desc limit 100) x),'[]'),
 'mode','LOCAL_QA','push_enabled',false);
end$$;
create table private.installation_operations (
 generation uuid primary key,
 kind text not null check(kind in ('BOOTSTRAP','ROTATE','REVOKE')),
 state text not null check(state in ('STARTED','COMMITTED','ACKNOWLEDGED','SEALED_START','SEALED_FORGOTTEN')),
 transport text not null check(transport in ('WEB','NATIVE')),
 pending_hash bytea,
 payload_hash bytea,
 prior_generation uuid,
 installation_id uuid references private.installations(id),
 prior_secret_hash bytea,
 prior_version integer,
 result_version integer,
 receipt_ciphertext text,
 created_at timestamptz not null default clock_timestamp(),
 deadline timestamptz not null default clock_timestamp()+interval '10 minutes',
 completed_at timestamptz,
 check(state<>'STARTED' or pending_hash is not null and payload_hash is not null)
);
alter table private.installation_operations enable row level security;
create index installation_pending_owner on private.installation_operations(installation_id) where state='STARTED';
create table private.installation_lifecycle_ledger (
 id uuid primary key default gen_random_uuid(),installation_id uuid not null references private.installations(id),
 generation uuid not null references private.installation_operations(generation),
 action text not null check(action in ('CAPABILITY_CREATE','CAPABILITY_ROTATE','CAPABILITY_REVOKE')),
 occurred_at timestamptz not null default clock_timestamp(),unique(generation,action)
);
alter table private.installation_lifecycle_ledger enable row level security;
create function private.installation_hash(p text) returns bytea language sql immutable set search_path='' as $$
 select extensions.digest(convert_to(p,'UTF8'),'sha256')
$$;
create function private.installation_active(p_install uuid,p_secret text,p_version integer) returns boolean language sql volatile set search_path='' as $$
 select length(p_secret)=64 and p_secret ~ '^[0-9a-f]{64}$' and exists(select 1 from private.installations
 where id=p_install and secret_hash=private.installation_hash(p_secret) and secret_version=p_version
 and revoked_at is null and expires_at>clock_timestamp())
$$;
create function public.installation_operation(p_action text,p_generation uuid,p_request jsonb) returns jsonb
 language plpgsql security definer set search_path='' as $$
declare o private.installation_operations;i private.installations;inserted integer;now_at timestamptz:=clock_timestamp();
 kind text:=p_request->>'kind';transport text:=p_request->>'transport';pending text:=p_request->>'pending';
 old_id uuid:=nullif(p_request->>'installation_id','')::uuid;old_secret text:=p_request->>'secret';
 old_version integer:=nullif(p_request->>'version','')::integer;result_id uuid;v_result_version integer;
begin
 perform private.assert_server();perform private.assert_initialized();
 if p_generation is null or jsonb_typeof(p_request)<>'object' then raise exception 'INVALID_INSTALLATION_OPERATION';end if;
 if p_action in ('START','COMMIT') then perform 1 from private.catalog_head where singleton for share;end if;
 if p_action='START_SEAL' then
  insert into private.installation_operations(generation,kind,state,transport)
  values(p_generation,'BOOTSTRAP','SEALED_START','WEB') on conflict do nothing;
  select * into strict o from private.installation_operations where generation=p_generation for update;
  if o.state='STARTED' then
   update private.installation_operations set state='SEALED_START',pending_hash=null,receipt_ciphertext=null where generation=p_generation;
   o.state:='SEALED_START';
  end if;
  return jsonb_build_object('state',o.state,'generation',p_generation,'server_time',clock_timestamp(),'deadline',o.deadline);
 end if;
 if p_action='START' then
  if kind is null or kind not in ('BOOTSTRAP','ROTATE','REVOKE') or transport is null or transport not in ('WEB','NATIVE')
   or pending is null or pending !~ '^[0-9a-f]{64}$' or p_request->>'payload_hash' is null
   or p_request->>'payload_hash' !~ '^[0-9a-f]{64}$' then raise exception 'INVALID_INSTALLATION_OPERATION';end if;
  if kind='BOOTSTRAP' then
   if old_id is not null or old_secret is not null or old_version is not null then raise exception 'BOOTSTRAP_SESSION_CONFLICT';end if;
  else
   if not coalesce(private.installation_active(old_id,old_secret,old_version),false) then raise exception 'INSTALLATION_UNAUTHORIZED' using errcode='42501';end if;
   perform 1 from private.installations where id=old_id for update;
   if exists(select 1 from private.installation_operations where installation_id=old_id and state='STARTED' and deadline>now_at) then raise exception 'OPERATION_PENDING';end if;
  end if;
  insert into private.installation_operations(generation,kind,state,transport,pending_hash,payload_hash,prior_generation,installation_id,prior_secret_hash,prior_version)
  values(p_generation,kind,'STARTED',transport,private.installation_hash(pending),decode(p_request->>'payload_hash','hex'),
   nullif(p_request->>'prior_generation','')::uuid,old_id,case when old_secret is not null then private.installation_hash(old_secret) end,old_version)
  on conflict do nothing;
  get diagnostics inserted=row_count;
  select * into strict o from private.installation_operations where generation=p_generation for update;
  if inserted=0 then raise exception 'GENERATION_ALREADY_EXISTS';end if;
  return jsonb_build_object('state','STARTED','generation',p_generation,'deadline',o.deadline);
 end if;
 select * into o from private.installation_operations where generation=p_generation for update;
 if not found then return jsonb_build_object('state','NONE','generation',p_generation,'server_time',now_at);end if;
 if p_action='GENERATION_STATE' then
  return jsonb_build_object('state',o.state,'generation',p_generation,'deadline',o.deadline,'server_time',now_at);
 end if;
 if p_action='GENERATION_FORGET' then
  if o.state='SEALED_FORGOTTEN' then return jsonb_build_object('state',o.state,'generation',p_generation);end if;
  if o.state not in ('COMMITTED','ACKNOWLEDGED') or o.deadline>now_at or p_request->'confirmed' is distinct from 'true'::jsonb then raise exception 'FORGET_NOT_READY';end if;
  update private.installation_operations set state='SEALED_FORGOTTEN',pending_hash=null,receipt_ciphertext=null where generation=p_generation;
  return jsonb_build_object('state','SEALED_FORGOTTEN','generation',p_generation,'server_time',now_at);
 end if;
 if p_action not in ('STATE','COMMIT','ACK') then raise exception 'INVALID_INSTALLATION_ACTION';end if;
 if o.state in ('SEALED_START','SEALED_FORGOTTEN') then raise exception 'GENERATION_SEALED';end if;
 if pending is null or private.installation_hash(pending) is distinct from o.pending_hash then raise exception 'PENDING_COOKIE_REQUIRED' using errcode='42501';end if;
 if transport is distinct from o.transport or decode(p_request->>'payload_hash','hex') is distinct from o.payload_hash then raise exception 'OPERATION_PAYLOAD_CONFLICT';end if;
 if p_action='STATE' then
  return jsonb_build_object('state',o.state,'generation',p_generation,'kind',o.kind,'deadline',o.deadline,'server_time',now_at);
 end if;
 if p_action='ACK' then
  if o.state not in ('COMMITTED','ACKNOWLEDGED') then raise exception 'OPERATION_NOT_COMMITTED';end if;
  if o.kind<>'REVOKE' and not coalesce(private.installation_active(old_id,old_secret,old_version),false) then raise exception 'INSTALLATION_UNAUTHORIZED' using errcode='42501';end if;
  if o.kind<>'REVOKE' and (old_id is distinct from o.installation_id or old_version is distinct from o.result_version) then raise exception 'OPERATION_OWNER_CONFLICT';end if;
  update private.installation_operations set state='ACKNOWLEDGED',receipt_ciphertext=null where generation=p_generation;
  return jsonb_build_object('state','ACKNOWLEDGED','generation',p_generation,'kind',o.kind);
 end if;
 if now_at>=o.deadline then raise exception 'OPERATION_EXPIRED';end if;
 if o.kind<>'BOOTSTRAP' and (old_id is distinct from o.installation_id or old_version is distinct from o.prior_version
  or private.installation_hash(old_secret) is distinct from o.prior_secret_hash) then raise exception 'OPERATION_OWNER_CONFLICT';end if;
 if o.state='COMMITTED' then
  -- Only the original nonce, payload, prior capability and live receipt recover a result.
  return jsonb_build_object('state','COMMITTED','generation',p_generation,'kind',o.kind,'receipt_ciphertext',o.receipt_ciphertext,'deadline',o.deadline);
 end if;
 if o.state<>'STARTED' then raise exception 'OPERATION_TERMINAL';end if;
 if o.kind='BOOTSTRAP' then
  result_id:=(p_request->>'new_id')::uuid;v_result_version:=1;
  if p_request->>'new_secret' is null or p_request->>'new_secret' !~ '^[0-9a-f]{64}$' then raise exception 'INVALID_SERVER_SECRET';end if;
  insert into private.installations(id,secret_hash,expires_at) values(result_id,private.installation_hash(p_request->>'new_secret'),now_at+interval '24 hours');
  insert into private.installation_settings(installation_id) values(result_id);
 else
  if not coalesce(private.installation_active(old_id,old_secret,old_version),false) then raise exception 'INSTALLATION_UNAUTHORIZED' using errcode='42501';end if;
  select * into strict i from private.installations where id=old_id for update;
  -- Recheck after acquiring the lock, including expiry and competing revocation/rotation.
  if not coalesce(private.installation_active(old_id,old_secret,old_version),false) then raise exception 'INSTALLATION_UNAUTHORIZED' using errcode='42501';end if;
  result_id:=old_id;v_result_version:=old_version+1;
  if o.kind='ROTATE' then
   if p_request->>'new_secret' is null or p_request->>'new_secret' !~ '^[0-9a-f]{64}$' then raise exception 'INVALID_SERVER_SECRET';end if;
   update private.installations set secret_hash=private.installation_hash(p_request->>'new_secret'),secret_version=v_result_version,expires_at=now_at+interval '24 hours' where id=old_id;
  else
   update private.installations set revoked_at=now_at,secret_version=v_result_version where id=old_id;
   update private.installation_settings set morning_issue=false,closing_issue=false,favorite_sector_issue=false,sector_ids='{}' where installation_id=old_id;
   update private.notification_deliveries set status='CANCELLED' where installation_id=old_id and status='NOT_SENT';
  end if;
 end if;
 if o.kind<>'REVOKE' and (p_request->>'receipt_ciphertext' is null or length(p_request->>'receipt_ciphertext')>4096) then raise exception 'INVALID_RECEIPT';end if;
 update private.installation_operations set state='COMMITTED',installation_id=result_id,result_version=v_result_version,
  receipt_ciphertext=case when o.kind='REVOKE' then null else p_request->>'receipt_ciphertext' end,completed_at=now_at where generation=p_generation;
 insert into private.installation_lifecycle_ledger(installation_id,generation,action) values(result_id,p_generation,
  case o.kind when 'BOOTSTRAP' then 'CAPABILITY_CREATE' when 'ROTATE' then 'CAPABILITY_ROTATE' else 'CAPABILITY_REVOKE' end);
 return jsonb_build_object('state','COMMITTED','generation',p_generation,'kind',o.kind,'receipt_ciphertext',
  case when o.kind='REVOKE' then null else p_request->>'receipt_ciphertext' end,'deadline',o.deadline);
end$$;
create table private.installation_view_tickets (
 id uuid primary key default gen_random_uuid(),installation_id uuid not null references private.installations(id),
 visit_id uuid not null,issue_id uuid not null references private.issues(id),version_id uuid not null references private.article_versions(id),
 issued_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null default clock_timestamp()+interval '30 minutes',
 unique(installation_id,visit_id)
);
create table private.installation_qa_views (
 id uuid primary key default gen_random_uuid(),installation_id uuid not null references private.installations(id),
 event_key uuid not null,ticket_id uuid not null unique references private.installation_view_tickets(id),
 issue_id uuid not null references private.issues(id),version_id uuid not null references private.article_versions(id),
 accepted_at timestamptz not null default clock_timestamp(),unique(installation_id,event_key)
);
create index installation_qa_views_time on private.installation_qa_views(accepted_at);
create index installation_qa_views_cooldown on private.installation_qa_views(installation_id,issue_id,accepted_at desc);
create table private.installation_view_outcomes (
 installation_id uuid not null references private.installations(id),event_key uuid not null,
 ticket_id uuid not null references private.installation_view_tickets(id),result jsonb not null,
 created_at timestamptz not null default clock_timestamp(),primary key(installation_id,event_key)
);
create table private.installation_qa_daily (
 issue_id uuid not null references private.issues(id),day date not null,pv bigint not null check(pv>=0),uv bigint not null check(uv>=0),
 mode text not null default 'LOCAL_QA' check(mode='LOCAL_QA'),provenance text not null default 'ACCEPTED_CANONICAL_AT_KST_DAY',
 updated_at timestamptz not null default clock_timestamp(),primary key(issue_id,day)
);
create table private.installation_qa_coverage (
 singleton boolean primary key default true check(singleton),started_at timestamptz not null default clock_timestamp(),
 collected_through timestamptz not null default clock_timestamp(),gap_since timestamptz,
 mode text not null default 'LOCAL_QA' check(mode='LOCAL_QA')
);
create table private.installation_retention_ledger (
 id uuid primary key default gen_random_uuid(),action text not null default 'RETENTION_TTL' check(action='RETENTION_TTL'),
 raw_deleted integer not null,daily_deleted integer not null,tickets_deleted integer not null,history_deleted integer not null,
 occurred_at timestamptz not null default clock_timestamp()
);
insert into private.installation_qa_coverage(singleton) values(true);
alter table private.installation_view_tickets enable row level security;
alter table private.installation_qa_views enable row level security;
alter table private.installation_view_outcomes enable row level security;
alter table private.installation_qa_daily enable row level security;
alter table private.installation_qa_coverage enable row level security;
alter table private.installation_retention_ledger enable row level security;
create function private.installation_canonical(p_issue uuid) returns uuid language plpgsql stable set search_path='' as $$
declare current_id uuid:=p_issue;next_id uuid;seen uuid[]:='{}';n integer;
begin
 for n in 1..16 loop
  if current_id=any(seen) then raise exception 'ALIAS_CYCLE';end if;seen:=array_append(seen,current_id);
  select canonical_issue_id into next_id from private.issue_aliases where alias_id=current_id;
  if not found then return current_id;end if;current_id:=next_id;
 end loop;
 raise exception 'ALIAS_CHAIN_LIMIT';
end$$;
create function public.installation_view(p_action text,p_install uuid,p_secret text,p_version integer,p_request jsonb) returns jsonb
 language plpgsql security definer set search_path='' as $$
declare canonical uuid;v uuid;t private.installation_view_tickets;v_event private.installation_view_outcomes;visit uuid;outcome jsonb;
 at_time timestamptz:=clock_timestamp();day_key date;
begin
 perform private.assert_server();perform private.assert_initialized();
 perform 1 from private.catalog_head where singleton for share;
 perform private.assert_installation(p_install,p_secret,p_version);
 -- Serialize accepts per installation before the cooldown and unique-key checks.
 perform 1 from private.installations where id=p_install for update;
 perform private.assert_installation(p_install,p_secret,p_version);
 at_time:=clock_timestamp();
 if p_action='TICKET' then
  visit:=(p_request->>'visit_id')::uuid;v:=(p_request->>'version_id')::uuid;
  canonical:=private.installation_canonical((p_request->>'issue_id')::uuid);
  perform 1 from private.issues where id=canonical for share;
  if visit is null or v is null or not exists(select 1 from private.issues i join private.article_versions av on av.id=i.current_version_id
   where i.id=canonical and i.current_version_id=v and i.publication_state='PUBLISHED' and i.sample_kind='SYNTHETIC' and av.public_body->>'_contract'='M1' and private.m1_current_evidence(i.id)) then raise exception 'ARTICLE_NOT_CURRENT';end if;
  insert into private.installation_view_tickets(installation_id,visit_id,issue_id,version_id) values(p_install,visit,canonical,v) on conflict do nothing;
  select * into strict t from private.installation_view_tickets where installation_id=p_install and visit_id=visit;
  if t.issue_id<>canonical or t.version_id<>v then raise exception 'VISIT_PAYLOAD_CONFLICT';end if;
  return jsonb_build_object('ticket_id',t.id,'issue_id',t.issue_id,'version_id',t.version_id,'issued_at',t.issued_at,'expires_at',t.expires_at,'mode','LOCAL_QA');
 end if;
 if p_action<>'ACCEPT' or p_request->>'event_key' is null then raise exception 'INVALID_VIEW_ACTION';end if;
 select * into t from private.installation_view_tickets where id=(p_request->>'ticket_id')::uuid and installation_id=p_install for update;
 if not found then raise exception 'VIEW_TICKET_INVALID';end if;
 select * into v_event from private.installation_view_outcomes where installation_id=p_install and event_key=(p_request->>'event_key')::uuid;
 if found then
  if v_event.ticket_id<>t.id then raise exception 'VIEW_EVENT_PAYLOAD_CONFLICT';end if;
  return v_event.result||jsonb_build_object('duplicate',true);
 end if;
 if exists(select 1 from private.installation_qa_views where ticket_id=t.id) then raise exception 'VISIT_ALREADY_RECORDED';end if;
 if at_time<t.issued_at+interval '3 seconds' then raise exception 'VIEW_TOO_EARLY';end if;
 if at_time>=t.expires_at then raise exception 'VIEW_TICKET_EXPIRED';end if;
 canonical:=private.installation_canonical(t.issue_id);
 perform 1 from private.issues where id=canonical for share;
 if canonical<>t.issue_id or not exists(select 1 from private.issues i where i.id=t.issue_id and i.current_version_id=t.version_id
  and i.publication_state='PUBLISHED' and i.sample_kind='SYNTHETIC' and private.m1_current_evidence(i.id)) then raise exception 'ARTICLE_NOT_CURRENT';end if;
 if exists(select 1 from private.installation_qa_views e where e.installation_id=p_install
  and private.installation_canonical(e.issue_id)=canonical and e.accepted_at>at_time-interval '60 seconds') then
  outcome:=jsonb_build_object('state','EXCLUDED','reason','INSTALLATION_ISSUE_COOLDOWN','mode','LOCAL_QA');
  insert into private.installation_view_outcomes(installation_id,event_key,ticket_id,result) values(p_install,(p_request->>'event_key')::uuid,t.id,outcome);
  return outcome;
 end if;
 insert into private.installation_qa_views(installation_id,event_key,ticket_id,issue_id,version_id,accepted_at)
 values(p_install,(p_request->>'event_key')::uuid,t.id,t.issue_id,t.version_id,at_time);
 day_key:=(at_time at time zone 'Asia/Seoul')::date;
 insert into private.installation_qa_daily(issue_id,day,pv,uv) values(t.issue_id,day_key,0,0) on conflict do nothing;
 perform 1 from private.installation_qa_daily where issue_id=t.issue_id and day=day_key for update;
 insert into private.installation_qa_daily(issue_id,day,pv,uv)
 select t.issue_id,day_key,count(*),count(distinct installation_id) from private.installation_qa_views
 where issue_id=t.issue_id and accepted_at>=(day_key::timestamp at time zone 'Asia/Seoul') and accepted_at<((day_key+1)::timestamp at time zone 'Asia/Seoul')
 on conflict(issue_id,day) do update set pv=excluded.pv,uv=excluded.uv,updated_at=at_time;
 update private.installation_qa_coverage set collected_through=at_time where singleton;
 outcome:=jsonb_build_object('state','ACCEPTED','duplicate',false,'mode','LOCAL_QA');
 insert into private.installation_view_outcomes(installation_id,event_key,ticket_id,result) values(p_install,(p_request->>'event_key')::uuid,t.id,outcome);
 return outcome;
end$$;
create function public.installation_admin_stats(p_start timestamptz,p_end timestamptz,p_issue uuid default null,p_sector uuid default null) returns jsonb
 language plpgsql stable security definer set search_path='' as $$
declare as_of timestamptz:=statement_timestamp();c private.installation_qa_coverage;quality text;rows jsonb;
begin
 perform private.m1_assert_editor();perform private.assert_initialized();
 if p_start is null or p_end is null or p_start>=p_end or p_end>as_of then raise exception 'INVALID_STATS_PERIOD';end if;
 select * into strict c from private.installation_qa_coverage where singleton;
 quality:=case when p_start<as_of-interval '30 days'+interval '1 hour' then 'UNSUPPORTED'
  when p_start<c.started_at or p_end>c.collected_through or c.gap_since is not null and c.gap_since<p_end then 'PARTIAL' else 'COMPLETE' end;
 if quality='UNSUPPORTED' then
  -- Daily UV is historical per original issue/day, never a period UV or sum of UVs.
  select coalesce(jsonb_agg(jsonb_build_object('issue_id',d.issue_id,'day',d.day,'pv',d.pv,
   'daily_uv',case when private.installation_canonical(d.issue_id)=d.issue_id and not exists(select 1 from private.issue_aliases a where a.canonical_issue_id=d.issue_id) then d.uv else null end,
   'uv_quality',case when private.installation_canonical(d.issue_id)<>d.issue_id or exists(select 1 from private.issue_aliases a where a.canonical_issue_id=d.issue_id) then 'UNAVAILABLE_MERGED_UV' else 'HISTORICAL_ORIGINAL_ISSUE_DAY' end,
   'provenance',d.provenance) order by d.day,d.issue_id),'[]') into rows
  from private.installation_qa_daily d join private.issues i on i.id=d.issue_id
  where d.day>=((greatest(p_start,as_of-interval '1 year')) at time zone 'Asia/Seoul')::date and d.day<=(p_end at time zone 'Asia/Seoul')::date
   and (p_issue is null or private.installation_canonical(d.issue_id)=private.installation_canonical(p_issue))
   and (p_sector is null or i.primary_sector_id=p_sector);
  return jsonb_build_object('mode','LOCAL_QA','as_of',as_of,'quality',quality,'period_uv',null,'daily_history',rows,'operational_pv',0,'operational_uv',0,'ranking_use',false,
   'inflow','UNSUPPORTED','original_source_clicks','UNSUPPORTED','collection_started_at',c.started_at,'collected_through',c.collected_through);
 end if;
 select coalesce(jsonb_agg(x order by x.pv desc,x.issue_id),'[]') into rows from
 (select private.installation_canonical(e.issue_id) issue_id,count(*) pv,count(distinct e.installation_id) uv
  from private.installation_qa_views e join private.issues i on i.id=private.installation_canonical(e.issue_id)
  where e.accepted_at>=greatest(p_start,as_of-interval '30 days') and e.accepted_at<p_end
   and (p_issue is null or private.installation_canonical(e.issue_id)=private.installation_canonical(p_issue)) and (p_sector is null or i.primary_sector_id=p_sector)
  group by private.installation_canonical(e.issue_id)) x;
 return jsonb_build_object('mode','LOCAL_QA','as_of',as_of,'quality',quality,'items',rows,'period_uv',case when quality='COMPLETE' then (select count(distinct e.installation_id)
  from private.installation_qa_views e join private.issues i on i.id=private.installation_canonical(e.issue_id)
  where e.accepted_at>=p_start and e.accepted_at<p_end and (p_issue is null or i.id=private.installation_canonical(p_issue)) and (p_sector is null or i.primary_sector_id=p_sector)) else null end,
  'operational_pv',0,'operational_uv',0,'ranking_use',false,'inflow','UNSUPPORTED','original_source_clicks','UNSUPPORTED','collection_started_at',c.started_at,'collected_through',c.collected_through);
end$$;
create function public.installation_qa_purge() returns jsonb language plpgsql security definer set search_path='' as $$
declare raw_count integer;daily_count integer;ticket_count integer;history_count integer;
begin
 perform private.assert_server();perform private.assert_initialized();
 delete from private.installation_qa_views where accepted_at<=clock_timestamp()-interval '30 days';get diagnostics raw_count=row_count;
 delete from private.installation_view_outcomes where created_at<=clock_timestamp()-interval '30 days';
 delete from private.installation_view_tickets t where expires_at<=clock_timestamp() and not exists(select 1 from private.installation_qa_views e where e.ticket_id=t.id)
  and not exists(select 1 from private.installation_view_outcomes e where e.ticket_id=t.id);get diagnostics ticket_count=row_count;
 delete from private.installation_qa_daily where day<((clock_timestamp()-interval '1 year') at time zone 'Asia/Seoul')::date;get diagnostics daily_count=row_count;
 delete from private.installation_setting_changes where occurred_at<=clock_timestamp()-interval '30 days';get diagnostics history_count=row_count;
 update private.installation_operations set receipt_ciphertext=null where deadline<=clock_timestamp() and receipt_ciphertext is not null;
 if raw_count+daily_count+ticket_count+history_count>0 then
  insert into private.installation_retention_ledger(raw_deleted,daily_deleted,tickets_deleted,history_deleted) values(raw_count,daily_count,ticket_count,history_count);
 end if;
 delete from private.installation_retention_ledger where occurred_at<clock_timestamp()-interval '1 year';
 return jsonb_build_object('mode','LOCAL_QA','raw_deleted',raw_count,'daily_deleted',daily_count,'tickets_deleted',ticket_count,'settings_history_deleted',history_count,'privacy_full_purge',false);
end$$;
alter function public.installation_settings_save(uuid,text,integer,bigint,bigint,boolean,boolean,boolean,uuid[]) rename to installation_settings_save_v1;
alter function public.installation_settings_save_v1(uuid,text,integer,bigint,bigint,boolean,boolean,boolean,uuid[]) set schema private;
create function public.installation_settings_save(p_install uuid,p_secret text,p_version integer,p_catalog bigint,p_revision bigint,
 p_morning boolean,p_closing boolean,p_favorite boolean,p_sectors uuid[]) returns jsonb
 language plpgsql security definer set search_path='' as $$
declare h bigint;
begin
 perform private.assert_server();perform private.assert_initialized();
 select version into h from private.catalog_head where singleton for share;
 if p_catalog is distinct from h then raise exception 'SETTINGS_CONFLICT';end if;
 if exists(select 1 from unnest(p_sectors) x where not private.catalog_sector_selectable(x,h,'SYNTHETIC')) then raise exception 'INACTIVE_SECTOR';end if;
 return private.installation_settings_save_v1(p_install,p_secret,p_version,p_catalog,p_revision,p_morning,p_closing,p_favorite,p_sectors);
end$$;
create function private.installation_seal_minimal() returns trigger language plpgsql set search_path='' as $$
begin
 if new.state in ('SEALED_START','SEALED_FORGOTTEN') then
  new.pending_hash:=null;new.payload_hash:=null;new.prior_generation:=null;new.installation_id:=null;
  new.prior_secret_hash:=null;new.prior_version:=null;new.result_version:=null;new.receipt_ciphertext:=null;
 end if;
 return new;
end$$;
create trigger installation_seal_minimal before insert or update on private.installation_operations
 for each row execute function private.installation_seal_minimal();
update private.installation_operations set pending_hash=null where state in ('SEALED_START','SEALED_FORGOTTEN');
alter function public.installation_settings_save(uuid,text,integer,bigint,bigint,boolean,boolean,boolean,uuid[]) rename to installation_settings_save_v2;
alter function public.installation_settings_save_v2(uuid,text,integer,bigint,bigint,boolean,boolean,boolean,uuid[]) set schema private;
create function public.installation_settings_save(p_install uuid,p_secret text,p_version integer,p_catalog bigint,p_revision bigint,
 p_morning boolean,p_closing boolean,p_favorite boolean,p_sectors uuid[]) returns jsonb
 language plpgsql security definer set search_path='' as $$
begin
 perform private.assert_server();perform private.assert_initialized();
 perform 1 from private.catalog_head where singleton for share;
 perform 1 from private.installations where id=p_install for update;
 perform private.assert_installation(p_install,p_secret,p_version);
 return private.installation_settings_save_v2(p_install,p_secret,p_version,p_catalog,p_revision,p_morning,p_closing,p_favorite,p_sectors);
end$$;
create function public.installation_qa_mark_gap(p_since timestamptz) returns jsonb
 language plpgsql security definer set search_path='' as $$
declare c private.installation_qa_coverage;
begin
 perform private.assert_server();perform private.assert_initialized();
 select * into strict c from private.installation_qa_coverage where singleton for update;
 if p_since is null or p_since<c.started_at or p_since>statement_timestamp() then raise exception 'INVALID_COVERAGE_GAP';end if;
 update private.installation_qa_coverage set gap_since=least(coalesce(gap_since,p_since),p_since) where singleton;
 return jsonb_build_object('mode','LOCAL_QA','state','GAP_RECORDED','gap_since',least(coalesce(c.gap_since,p_since),p_since));
end$$;
create or replace function public.installation_admin_stats(p_start timestamptz,p_end timestamptz,p_issue uuid default null,p_sector uuid default null) returns jsonb
 language plpgsql stable security definer set search_path='' as $$
declare as_of timestamptz:=statement_timestamp();c private.installation_qa_coverage;quality text;rows jsonb;
begin
 perform private.m1_assert_editor();perform private.assert_initialized();
 if p_start is null or p_end is null or p_start>=p_end or p_end>as_of then raise exception 'INVALID_STATS_PERIOD';end if;
 select * into strict c from private.installation_qa_coverage where singleton;
 quality:=case when p_start<as_of-interval '30 days'+interval '1 hour' then 'UNSUPPORTED'
  when p_start<c.started_at or c.gap_since is not null and c.gap_since<p_end then 'PARTIAL' else 'COMPLETE' end;
 if quality='UNSUPPORTED' then
  -- Daily UV is historical per original issue/day, never a period UV or sum of UVs.
  select coalesce(jsonb_agg(jsonb_build_object('issue_id',d.issue_id,'day',d.day,'pv',d.pv,
   'daily_uv',case when private.installation_canonical(d.issue_id)=d.issue_id and not exists(select 1 from private.issue_aliases a where a.canonical_issue_id=d.issue_id) then d.uv else null end,
   'uv_quality',case when private.installation_canonical(d.issue_id)<>d.issue_id or exists(select 1 from private.issue_aliases a where a.canonical_issue_id=d.issue_id) then 'UNAVAILABLE_MERGED_UV' else 'HISTORICAL_ORIGINAL_ISSUE_DAY' end,
   'provenance',d.provenance) order by d.day,d.issue_id),'[]') into rows
  from private.installation_qa_daily d join private.issues i on i.id=d.issue_id
  where d.day>=((greatest(p_start,as_of-interval '1 year')) at time zone 'Asia/Seoul')::date and d.day<=(p_end at time zone 'Asia/Seoul')::date
   and (p_issue is null or private.installation_canonical(d.issue_id)=private.installation_canonical(p_issue))
   and (p_sector is null or i.primary_sector_id=p_sector);
  return jsonb_build_object('mode','LOCAL_QA','as_of',as_of,'window_start',p_start,'window_end',p_end,'coverage_semantics','ACCEPTED_SERVER_EVENTS_SNAPSHOT','quality',quality,'period_uv',null,'daily_history',rows,'operational_pv',0,'operational_uv',0,'ranking_use',false,
   'inflow','UNSUPPORTED','original_source_clicks','UNSUPPORTED','collection_started_at',c.started_at,'collected_through',case when c.gap_since is null then as_of else least(c.gap_since,as_of) end,'last_accepted_at',(select max(accepted_at) from private.installation_qa_views));
 end if;
 select coalesce(jsonb_agg(x order by x.pv desc,x.issue_id),'[]') into rows from
 (select private.installation_canonical(e.issue_id) issue_id,count(*) pv,case when quality='COMPLETE' then count(distinct e.installation_id) else null end uv
  from private.installation_qa_views e join private.issues i on i.id=private.installation_canonical(e.issue_id)
  where e.accepted_at>=greatest(p_start,as_of-interval '30 days') and e.accepted_at<p_end
   and (p_issue is null or private.installation_canonical(e.issue_id)=private.installation_canonical(p_issue)) and (p_sector is null or i.primary_sector_id=p_sector)
  group by private.installation_canonical(e.issue_id)) x;
 return jsonb_build_object('mode','LOCAL_QA','as_of',as_of,'window_start',p_start,'window_end',p_end,'coverage_semantics','ACCEPTED_SERVER_EVENTS_SNAPSHOT','quality',quality,'items',rows,'period_uv',case when quality='COMPLETE' then (select count(distinct e.installation_id)
  from private.installation_qa_views e join private.issues i on i.id=private.installation_canonical(e.issue_id)
  where e.accepted_at>=p_start and e.accepted_at<p_end and (p_issue is null or i.id=private.installation_canonical(p_issue)) and (p_sector is null or i.primary_sector_id=p_sector)) else null end,
  'operational_pv',0,'operational_uv',0,'ranking_use',false,'inflow','UNSUPPORTED','original_source_clicks','UNSUPPORTED','collection_started_at',c.started_at,'collected_through',case when c.gap_since is null then as_of else least(c.gap_since,as_of) end,'last_accepted_at',(select max(accepted_at) from private.installation_qa_views));
end$$;$c08a_source$;
for rec in select cl.oid,ns.nspname,cl.relname from pg_class cl join pg_namespace ns on ns.oid=cl.relnamespace where ns.nspname='private' and cl.relname=any(array['installation_setting_changes','installation_operations','installation_lifecycle_ledger','installation_view_tickets','installation_qa_views','installation_view_outcomes','installation_qa_daily','installation_qa_coverage','installation_retention_ledger']) loop execute format('alter table %I.%I force row level security',rec.nspname,rec.relname);execute format('revoke all on table %I.%I from public,anon,authenticated,service_role',rec.nspname,rec.relname);execute format('revoke all on type %I.%I from public,anon,authenticated,service_role',rec.nspname,rec.relname);end loop;
for rec in select p.oid,p.oid::regprocedure::text as sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname||'.'||p.proname=any(array['private.installation_active','private.installation_canonical','private.installation_hash','private.installation_seal_minimal','private.installation_settings_json','private.installation_settings_revision','private.installation_settings_save_v1','private.installation_settings_save_v2','private.search_company_sectors','private.search_contains_all','private.search_membership_visible','private.search_normalize','private.search_tokens','public.catalog_public_company_sectors','public.catalog_public_saved','public.catalog_public_search_companies','public.catalog_public_search_news','public.installation_admin_stats','public.installation_operation','public.installation_qa_mark_gap','public.installation_qa_purge','public.installation_settings_read','public.installation_settings_save','public.installation_view']) loop execute 'revoke all on function '||rec.sig||' from public,anon,authenticated,service_role';if (select proacl::text from pg_proc where oid=rec.oid) is distinct from '{postgres=X/postgres}' then raise exception 'NEW_FUNCTION_EXACT_ACL';end if;end loop;
current_meta:=(jsonb_build_object('schemas',(select jsonb_agg(jsonb_build_array(nspname,pg_get_userbyid(nspowner),nspacl::text) order by nspname) from pg_namespace where nspname in ('private','judoju_control','public')),'relations',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,c.relkind,pg_get_userbyid(c.relowner),c.relacl::text,c.relrowsecurity,c.relforcerowsecurity,c.reloptions,case when c.relkind='v' then pg_get_viewdef(c.oid,true) else null end) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where (n.nspname in ('private','judoju_control') or n.nspname='public' and c.relname in ('news_public','news_list')) and c.relkind in ('r','p','v','m','f','S')),'columns',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attacl::text,a.attcollation::regcollation::text,pg_get_expr(d.adbin,d.adrelid)) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where (n.nspname in ('private','judoju_control') or n.nspname='public' and c.relname in ('news_public','news_list')) and a.attnum>0 and not a.attisdropped and c.relkind in ('r','p','v','m','f')),'constraints',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,x.conname,pg_get_constraintdef(x.oid,true)) order by n.nspname,c.relname,x.conname) from pg_constraint x join pg_class c on c.oid=x.conrelid join pg_namespace n on n.oid=c.relnamespace where (n.nspname in ('private','judoju_control') or n.nspname='public' and c.relname in ('news_public','news_list'))),'indexes',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,pg_get_indexdef(i.indexrelid)) order by n.nspname,c.relname,pg_get_indexdef(i.indexrelid)) from pg_index i join pg_class c on c.oid=i.indrelid join pg_namespace n on n.oid=c.relnamespace where (n.nspname 