if auth_before is distinct from auth_after or namespace_before is distinct from (select jsonb_build_object('name',n.nspname,'owner',pg_get_userbyid(n.nspowner),'acl',(select jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable) order by (case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end) collate "C",pg_get_userbyid(a.grantor) collate "C",a.privilege_type collate "C",a.is_grantable) from aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a)) from pg_namespace n where n.nspname='auth') then raise exception 'MANAGED_AUTH_OR_NAMESPACE_CHANGED';end if;
